    #[derive(Debug)]
    pub struct ReferencedShapes: usize {
        const Rect = 1 << 0;
        const Line = 1 << 1;
        const Polyline = 1 << 2;
        const Polygon = 1 << 3;
        const Circle = 1 << 4;
        const Ellipse = 1 << 5;
        const Path = 1 << 6;
