/// `<path>` definition.
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// # Errors
///
/// If a path has an invalid id.
pub struct ReusePaths(pub bool);

impl<'input, 'arena> Visitor<'input, 'arena> for ReusePaths {
