            defs.set_attribute(Attr::Unparsed {
                attr_id: AttrId::Unknown(QualName {
                    prefix: Prefix::XMLNS,
                    local: Prefix::XLink.value().unwrap(),
                }),
                value: NS::XLink.uri().clone(),
            });
        }

        Ok(())
    }
}

