                        .select(&subject_css)
                        .ok()
                        .is_some_and(|mut m| m.any(|e| e.id_eq(child)))
                })
                .collect(),
            Some(Combinator::NextSibling) => anchor
                .next_element_sibling()
                .filter(|sibling| {
