/// Serialises a single compound (a sequence of simple selectors without
/// combinators) in parse order.
fn compound_to_css<'input>(compound: &[Component<'input>]) -> Option<String> {
    let mut output = String::new();
    // Components are stored in match order (right-to-left within a compound),
    // so reverse to serialise in parse order.
    for component in compound.iter().rev() {
        component.to_css(&mut output).ok()?;
    }
    if output.is_empty() {
        return None;
    }
    Some(output)
}

/// Serialises a selector fragment given in match order (right-to-left).
fn components_to_css<'input>(components: &[Component<'input>]) -> Option<String> {
    let mut compounds: Vec<&[Component<'input>]> = Vec::new();
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut start = 0;
    for (i, component) in components.iter().enumerate() {
        if let Component::Combinator(combinator) = component {
            combinators.push(*combinator);
            compounds.push(&components[start..i]);
            start = i + 1;
        }
    }
    compounds.push(&components[start..]);
    compounds.reverse();
    combinators.reverse();

    let mut output = String::new();
    for (i, compound) in compounds.iter().enumerate() {
        if i > 0 {
            output.push(' ');
            output.push_str(&combinator_css(combinators[i - 1]));
            output.push(' ');
        }
        let css = compound_to_css(compound)?;
        output.push_str(&css);
    }
    Some(output)
}

fn combinator_css(combinator: Combinator) -> &'static str {
    match combinator {
        Combinator::Child => ">",
        Combinator::NextSibling => "+",
        Combinator::LaterSibling => "~",
        _ => "",
    }
}
