impl<'input, 'arena> Visitor<'input, 'arena> for State<'_, 'input, 'arena> {
    type Error = JobsError<'input>;

    fn is_plain_protected(&self, element: &Element<'input, 'arena>) -> bool {
        let name = match element.qual_name() {
            ElementId::Rect => "rect",
            ElementId::Line => "line",
            ElementId::Polyline => "polyline",
            ElementId::Polygon => "polygon",
            ElementId::Circle => "circle",
            ElementId::Ellipse => "ellipse",
            _ => return false,
        };
        self.plain_targets
            .get(name)
            .is_some_and(|targets| targets.contains(&oxvg_ast::element::HashableElement::new(element.clone())))
    }

    fn element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let name = element.qual_name();

        let options = &self.options;
        let path_options = &convert::Options {
            precision: options.float_precision.0,
            ..convert::Options::default()
        };
        let convert_arcs = options.convert_arcs;

        match name {
            ElementId::Rect if !self.is_plain_protected(element) && !self.implicated.contains(element) => {
                ConvertShapeToPath::rect_to_path(element, path_options, context.info);
            }
            ElementId::Line if !self.is_plain_protected(element) && !self.implicated.contains(element) => {
