                ConvertShapeToPath::poly_to_path(element, path_options, false, context.info);
            }
            ElementId::Polygon if !self.is_plain_protected(element) && !self.implicated.contains(element) => {
                ConvertShapeToPath::poly_to_path(element, path_options, true, context.info);
            }
            ElementId::Circle
                if convert_arcs && !self.is_plain_protected(element) && !self.implicated.contains(element) =>
            {
